function insightMetricValue(list,name){const item=(list||[]).find(x=>x.name===name);return item?.total_value?.value ?? item?.values?.[0]?.value ?? 0}
function metricBreakdowns(item){return item?.total_value?.breakdowns?.[0]?.results||item?.values?.[0]?.breakdowns?.[0]?.results||[]}
function mediaInsightValue(media,name){return insightMetricValue(media?.insights?.data||[],name)}
function insightMetricLabel(name){return ({reach:'リーチ',profile_views:'プロフィールアクセス',website_clicks:'ウェブサイトリンククリック',views:'閲覧/再生',follower_count:'フォロワー増減',follower_demographics:'フォロワー属性',reached_audience_demographics:'リーチしたユーザー属性',engaged_audience_demographics:'エンゲージしたユーザー属性',online_followers:'オンラインフォロワー',saved:'保存',shares:'シェア',total_interactions:'総インタラクション',likes:'いいね',comments:'コメント',follows:'フォロー',profile_visits:'プロフィール訪問',profile_activity:'プロフィールアクション',ig_reels_video_view_total_time:'リール総再生時間',ig_reels_avg_watch_time:'リール平均視聴時間',reels_skip_rate:'リールスキップ率',reposts:'リポスト',facebook_views:'Facebook再生',crossposted_views:'クロスポスト再生',total_views:'総閲覧/再生',total_likes:'総いいね',total_comments:'総コメント',link_clicks:'リンククリック',audience_retention_graph:'視聴維持率グラフ',retention_graph:'離脱/視聴維持グラフ'})[name]||name}
function insightRawValue(x){return x?.total_value?.value ?? x?.values?.[0]?.value ?? null}
function insightRows(list){return (list||[]).map(x=>{const raw=insightRawValue(x);return {name:x.name,label:insightMetricLabel(x.name),period:x.period||'',value:typeof raw==='number'?raw:null,rawValue:raw,description:x.description||x.title||'',breakdowns:metricBreakdowns(x)}})}
function transformBreakdowns(list,metricName){const item=(list||[]).find(x=>x.name===metricName&&metricBreakdowns(x).length);return metricBreakdowns(item).map(r=>{const dims=Object.entries(r.dimension_values||{}).map(([,v])=>v).join(' / ')||r.dimension_value||r.name||'未分類';return {label:dims, value:r.value||0}})}
function transformInstagramInsights(api){
  const profile=api?.profile||{};
  const metrics=api?.accountInsights||[];
  const reach=insightMetricValue(metrics,'reach');
  const views=insightMetricValue(metrics,'views');
  const profileViews=insightMetricValue(metrics,'profile_views');
  const websiteClicks=insightMetricValue(metrics,'website_clicks');
  const posts=(api?.media||[]).map((m,i)=>{
    const mReach=mediaInsightValue(m,'reach');
    const mViews=mediaInsightValue(m,'views');
    const saves=mediaInsightValue(m,'saved');
    const shares=mediaInsightValue(m,'shares');
    const totalInteractions=mediaInsightValue(m,'total_interactions');
    const likes=mediaInsightValue(m,'likes') || Number(m.like_count||0);
    const comments=mediaInsightValue(m,'comments') || Number(m.comments_count||0);
    const caption=String(m.caption||'').split(/\n/).filter(Boolean)[0]||`Instagram投稿 ${i+1}`;
    const metricRows=insightRows(m.insights?.data||[]);
    return {id:m.id,account:'@'+(profile.username||'instagram'),title:caption.slice(0,60),caption:m.caption||'',date:String(m.timestamp||'').slice(0,10)||'-',format:m.media_product_type||m.media_type||'投稿',reach:mReach,plays:mViews,likes,comments,saves,shares,totalInteractions,profileActions:totalInteractions,permalink:m.permalink,thumbnailUrl:m.thumbnail_url||m.media_url||'',mediaType:m.media_type,metrics:metricRows,unavailable:m.insight_errors||[]}
  });
  return {
    source:api?.source||'meta_graph_api',
    period:'Meta Graph API 実データ',
    selectedAccountKey:api?.selectedAccountKey||api?.selectedAccount?.key||'',
    accounts:(api?.accounts||[]).map(a=>({name:a.label||a.username||'Instagramアカウント',account:a.username?'@'+String(a.username).replace(/^@/,''):(a.label||a.key||'Instagramアカウント'),key:a.key||a.username||a.igBusinessAccountId,url:a.username?`https://www.instagram.com/${String(a.username).replace(/^@/,'')}/`:'#',igBusinessAccountId:a.igBusinessAccountId,role:'自社Instagram'})),
    account:{name:profile.name||profile.username||api?.selectedAccount?.label||'Instagramアカウント',account:'@'+(profile.username||api?.selectedAccount?.username||'instagram'),key:api?.selectedAccountKey||api?.selectedAccount?.key||profile.id,url:profile.username?`https://www.instagram.com/${profile.username}/`:'#',posts:profile.media_count,followers:profile.followers_count,following:profile.follows_count,profilePictureUrl:profile.profile_picture_url},
    accountSummary:{followers:profile.followers_count||0,following:profile.follows_count||0,mediaCount:profile.media_count||0,reach,views,profileViews,websiteClicks,engagementRate:(posts.reduce((a,p)=>a+(p.reach||0),0)||reach)?((posts.reduce((a,p)=>a+(p.totalInteractions||0),0)/(posts.reduce((a,p)=>a+(p.reach||0),0)||reach))*100):0},
    accountMetricRows:insightRows(metrics),
    demographics:{followersAgeGender:transformBreakdowns(metrics,'follower_demographics'),reachedAgeGender:transformBreakdowns(metrics,'reached_audience_demographics'),engagedAgeGender:transformBreakdowns(metrics,'engaged_audience_demographics')},
    posts,
    unavailableInsights:api?.unavailableInsights||[],
    note:api?.note||''
  }
}
async function refreshInstagramInsights(){
  if(state.instagramInsightsLoading)return;
  state.instagramInsightsLoading=true;state.instagramInsightsError='';
  try{const params=new URLSearchParams();if(state.selectedInstagramAccountKey)params.set('account',state.selectedInstagramAccountKey);const res=await fetch('/api/instagram-insights'+(params.toString()?`?${params}`:''),{cache:'no-store'});const json=await res.json();if(!res.ok||!json.ok)throw new Error(json.message||json.error||'instagram_insights_failed');state.instagramInsights=transformInstagramInsights(json);state.selectedInstagramAccountKey=state.instagramInsights.selectedAccountKey||state.selectedInstagramAccountKey}
  catch(e){state.instagramInsightsError=e.message||String(e);state.instagramInsights=null}
  finally{state.instagramInsightsLoading=false;if(state.authUser&&(state.view==='instagram'||state.view==='dashboard'))render()}
}
function setSelectedInstagramAccount(v){state.selectedInstagramAccountKey=v||'';state.instagramInsights=null;refreshInstagramInsights();render()}
function connectedInstagramAccounts(){return state.instagramInsights?.accounts?.length?state.instagramInsights.accounts:null}
function activeInstagramInsights(){return state.instagramInsights||null}
function realInstagramAccount(){return state.instagramInsights?.account||null}
function realInstagramVideos(){if(!state.instagramInsights?.posts)return null;return state.instagramInsights.posts.map((p,i)=>({id:p.id||('real-ig-'+i),title:p.title,media:'Instagram',type:p.format||'投稿',date:p.date,purpose:'実アカウントの投稿実績を確認する',views:p.plays||p.reach||0,accountVisits:0,formViews:0,saves:p.saves||0,follows:0,thumbnailUrl:p.thumbnailUrl||'',watchRate:'-',avgWatch:'-',opening:'-',theme:p.format||'Instagram',cast:'-',structure:'-',cta:'-',caption:p.title,tag:'実データ',ai:'Meta Graph APIから取得できた投稿指標のみ表示',next:'実取得指標を確認'}))}
function realInstagramRevisionPlan(){return null}
function insightRate(post){return post.reach&&post.totalInteractions!=null?((post.totalInteractions||0)/post.reach*100).toFixed(2)+'%':'-'}
function insightPostTable(rows){return rowsToTable(['投稿','アカウント','リーチ','再生/表示','保存','シェア','総反応','反応率'],rows.map(p=>`<tr><td><strong>${esc(p.title)}</strong><br><span class="muted small">${esc(p.date)} / ${esc(p.format)}</span>${p.permalink?`<br><a href="${esc(p.permalink)}" target="_blank" rel="noopener">投稿を開く</a>`:''}</td><td>${esc(p.account)}</td><td>${fmt(p.reach)}</td><td>${fmt(p.plays)}</td><td>${fmt(p.saves)}</td><td>${fmt(p.shares)}</td><td>${fmt(p.totalInteractions)}</td><td><strong>${insightRate(p)}</strong></td></tr>`))}


function setSelectedInstagramVideo(id){state.selectedInstagramVideoId=id||'';render()}
function numericPostMetrics(p){return (p?.metrics||[]).filter(m=>typeof m.value==='number'&&Number.isFinite(m.value)).map(m=>({label:m.label||m.name,name:m.name,value:m.value}))}
function parseRetentionPoints(p){const rows=(p?.metrics||[]).filter(m=>['audience_retention_graph','retention_graph'].includes(m.name));for(const m of rows){const raw=m.rawValue;if(Array.isArray(raw)){return raw.map((v,i)=>({label:String(i),value:typeof v==='number'?v:Number(v.value??v.retention??v.percentage??0)})).filter(x=>Number.isFinite(x.value))}if(raw&&typeof raw==='object'){return Object.entries(raw).map(([k,v])=>({label:k,value:typeof v==='number'?v:Number(v.value??v.retention??v.percentage??0)})).filter(x=>Number.isFinite(x.value))}}return []}
function simpleLineSvg(points,{title='',unit='',height=230,width=720,color='#2563eb'}={}){if(!points||points.length<1)return '<p class="muted">グラフ化できる数値がありません。</p>';const vals=points.map(p=>Number(p.value)||0);const max=Math.max(...vals,1),min=Math.min(...vals,0),span=Math.max(max-min,1);const left=58,right=24,top=24,bottom=46;const plotW=width-left-right,plotH=height-top-bottom;const x=i=>left+(i*(plotW/Math.max(points.length-1,1)));const y=v=>top+plotH-(((Number(v)||0)-min)/span)*plotH;const pts=points.map((p,i)=>`${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(' ');const circles=points.map((p,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${y(p.value).toFixed(1)}" r="4"><title>${esc(p.label)}: ${fmt(p.value)}${esc(unit)}</title></circle>`).join('');const labels=points.map((p,i)=>i%Math.ceil(points.length/6)===0||i===points.length-1?`<text x="${x(i).toFixed(1)}" y="${height-18}" text-anchor="middle">${esc(String(p.label).slice(0,10))}</text>`:'').join('');return `<div class="ig-line-chart"><div class="chart-head"><strong>${esc(title)}</strong><span>${fmt(min)}〜${fmt(max)}${esc(unit)}</span></div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}"><line x1="${left}" y1="${top}" x2="${left}" y2="${top+plotH}"/><line x1="${left}" y1="${top+plotH}" x2="${width-right}" y2="${top+plotH}"/><text x="8" y="${top+8}">${fmt(max)}${esc(unit)}</text><text x="8" y="${top+plotH}">${fmt(min)}${esc(unit)}</text><polyline points="${pts}" fill="none" stroke="${esc(color)}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${circles}${labels}</svg></div>`}
function metricLineForPost(p){const preferred=['views','reach','total_views','total_interactions','likes','comments','saved','shares','reposts','reels_skip_rate','ig_reels_avg_watch_time','ig_reels_video_view_total_time'];const nums=numericPostMetrics(p);const ordered=[...preferred.map(n=>nums.find(x=>x.name===n)).filter(Boolean),...nums.filter(x=>!preferred.includes(x.name))];return simpleLineSvg(ordered.map(x=>({label:x.label,value:x.value})),{title:'選択動画の取得インサイト（指標別）',unit:'',color:'#7c3aed'})}
function retentionPanel(p){const points=parseRetentionPoints(p);const skip=(p?.metrics||[]).find(m=>m.name==='reels_skip_rate');const avg=(p?.metrics||[]).find(m=>m.name==='ig_reels_avg_watch_time');const total=(p?.metrics||[]).find(m=>m.name==='ig_reels_video_view_total_time');if(points.length){return `<section class="instagram-card mini-section"><h3>離脱タイミング / 視聴維持率</h3>${simpleLineSvg(points,{title:'離脱タイミング（Meta API返却値）',unit:'%',color:'#ef4444'})}</section>`}return `<section class="instagram-card mini-section"><h3>離脱タイミング / 視聴維持率</h3><p class="muted">この投稿ではMeta Graph APIから秒別・区間別の離脱タイミング配列は返却されていません。推定値は混ぜず、取得できた近接指標のみ表示します。</p><div class="grid layout-3">${metric('リールスキップ率',skip?.value!=null?String(skip.value)+'%':'-','冒頭3秒以内の離脱率')}${metric('平均視聴時間',avg?.value!=null?igDuration(avg.value):'-','1再生あたり平均')}${metric('総再生時間',total?.value!=null?igDuration(total.value):'-','全再生の合計時間')}</div></section>`}
function selectedPostGraphPanel(posts){if(!posts?.length)return '';const selected=posts.find(p=>p.id===state.selectedInstagramVideoId)||posts[0];if(!state.selectedInstagramVideoId)state.selectedInstagramVideoId=selected.id;const options=posts.map(p=>`<option value="${esc(p.id)}" ${p.id===selected.id?'selected':''}>${esc(p.date)} / ${esc(p.title)}</option>`).join('');const unavailable=(selected.unavailable||[]).slice(0,8);return `<details class="ig-accordion" open><summary><div><strong>動画別インサイトグラフ</strong><span>対象動画を選ぶと、取得済み指標をグラフ表示します</span></div><em>展開中</em></summary><div class="ig-accordion-body"><label class="ig-edit-label">対象動画<select onchange="setSelectedInstagramVideo(this.value)">${options}</select></label><div class="grid layout-2" style="margin-top:14px"><section class="instagram-card mini-section"><h3>${esc(selected.title)}</h3>${metricLineForPost(selected)}</section>${retentionPanel(selected)}</div>${unavailable.length?`<div style="margin-top:14px"><h4>この動画でMeta APIが返さない項目</h4>${unavailableInsightsHtml(unavailable)}</div>`:''}</div></details>`}

function previewDateRange(){return {start:localStorage.getItem('ig_preview_start')||'2026-07-01',end:localStorage.getItem('ig_preview_end')||'2026-08-03'}}
function setPreviewDateRange(k,v){localStorage.setItem(k==='start'?'ig_preview_start':'ig_preview_end',v);render()}
function previewCompanyName(){return localStorage.getItem('ig_preview_company')||activeCompany().companyName}
