function setIgSortMode(v){state.igSortMode=v||'score';render()}
function isMultipleAccounts(){return activeAccounts().length>1}
function stockTrend(current,previous,label='前期間比'){const cur=Number(current||0),prev=Number(previous||0);const diff=cur-prev;const up=diff>=0;const arrow=up?'▲':'▼';const raw=prev?Math.abs((diff/prev)*100).toFixed(1)+'%':fmt(Math.abs(diff));return `<span class="stock-trend ${up?'up':'down'}"><b>${arrow}</b><span>${esc(label)} ${up?'+':'-'}${esc(raw)}</span></span>`}
function metricTrend(label,val,note,current,previous){return `<div class="card kpi-trend-card"><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(val)}</div><div class="metric-note">${esc(note)}</div>${stockTrend(current,previous)}</div>`}
