function insightPostLink(p,inner){return p.permalink?`<a href="${esc(p.permalink)}" target="_blank" rel="noopener">${inner}</a>`:inner}
function postBioClicks(p,i,summary){return p.bioLinkClicks??p.websiteClicks??null}
function postProfileAccesses(p,i,summary){return p.profileAccesses??null}
function postScore(p,i,summary){return (p.plays||0)*.35+(p.saves||0)*32+postBioClicks(p,i,summary)*70+(p.likes||0)*5+(p.comments||0)*16}
function sortInsightPosts(posts,summary){const mode=state.igSortMode||'score';return [...posts].sort((a,b)=>mode==='date'?String(b.date).localeCompare(String(a.date)):postScore(b,0,summary)-postScore(a,0,summary))}
function previewBarRows(data,labelKey='label'){const max=Math.max(...data.map(x=>x.share||x.count||0),1);return data.map(x=>{const label=x[labelKey]||x.label;const val=x.share!=null?x.share+'%':fmt(x.count);const w=Math.max(3,((x.share||x.count||0)/max)*100);return `<article class="ig-bar-row"><div><strong>${esc(label)}</strong><span>${esc(val)}</span></div><div class="ig-bar-track"><span style="width:${w}%"></span></div></article>`}).join('')}
function openActiveTimeDetail(){const el=document.getElementById('active_time_modal');if(el){el.classList.add('show');document.body.classList.add('modal-open')}}
function closeActiveTimeDetail(){const el=document.getElementById('active_time_modal');if(el){el.classList.remove('show');document.body.classList.remove('modal-open')}}
function previewHeatmap(rows){const hours=['8時','11時','14時','17時','20時','22時','24時'];const cells=[];rows.forEach(r=>r.slice(1).forEach((v,i)=>cells.push({day:r[0],hour:hours[i],score:Number(v)||0})));const top=[...cells].sort((a,b)=>b.score-a.score).slice(0,3);const max=Math.max(...cells.map(x=>x.score),1);const dayCards=rows.map(r=>{const values=r.slice(1).map((v,i)=>({hour:hours[i],score:Number(v)||0}));const best=[...values].sort((a,b)=>b.score-a.score)[0];const segments=values.map(x=>`<span class="active-segment ${x.score>=80?'hot':x.score>=60?'warm':''}" style="height:${Math.max(16,18+(x.score/max)*54)}px" title="${esc(r[0])} ${esc(x.hour)} ${x.score}"><em>${esc(x.hour)}</em><strong>${x.score}</strong></span>`).join('');return `<article class="active-day-card"><div class="active-day-head"><strong>${esc(r[0])}</strong><span>最適 ${esc(best.hour)} / ${best.score}</span></div><div class="active-day-bars">${segments}</div></article>`}).join('');const detail=`<div class="active-time-redesign"><div class="active-recommend"><div><span class="badge">AIおすすめ投稿日時</span><h4>水曜 20:30 / 木曜 21:00 を優先</h4><p>曜日別のピークと時間帯の山が一目で分かるカード型です。採用系リールは20〜22時、社員紹介は木曜21時を推奨します。</p></div><div class="active-top-slots">${top.map((x,i)=>`<article><b>${i+1}</b><strong>${esc(x.day)} ${esc(x.hour)}</strong><span>反応スコア ${x.score}</span></article>`).join('')}</div></div><div class="active-time-legend"><span><i class="hot"></i>最優先</span><span><i class="warm"></i>有望</span><span><i></i>通常</span></div><div class="active-day-list">${dayCards}</div></div>`;return `<div class="active-compact"><div><strong>おすすめ投稿時間</strong><p>水曜20:30 / 木曜21:00 を優先。詳細グラフは必要な時だけ中央表示します。</p><div class="active-mini-slots">${top.map(x=>`<span>${esc(x.day)} ${esc(x.hour)}：${x.score}</span>`).join('')}</div></div><button class="mini-btn primary" onclick="openActiveTimeDetail()">詳細グラフを見る</button></div><div id="active_time_modal" class="active-modal" role="dialog" aria-modal="true"><div class="active-modal-backdrop" onclick="closeActiveTimeDetail()"></div><div class="active-modal-panel"><div class="active-modal-head"><div><span class="badge">時間帯分析</span><h3>アクティブ時間帯 詳細グラフ</h3></div><button class="mini-btn ghost" onclick="closeActiveTimeDetail()">閉じる</button></div>${detail}</div></div>`}
function benchmarkTable(rows){return rowsToTable(['アカウント','フォロワー','平均再生','リンククリック率','反応率'],rows.map(x=>`<tr><td><strong>${esc(x.account)}</strong></td><td>${fmt(x.followers)}</td><td>${fmt(x.avgViews)}</td><td>${esc(x.clickRate)}%</td><td>${esc(x.interactionRate)}%</td></tr>`))}
