function instagramPostCards(rows,summary,ins={}){return `<div class="ig-post-grid">${rows.map((p,i)=>{const interactions=p.totalInteractions??((p.likes||0)+(p.comments||0)+(p.saves||0)+(p.shares||0));const thumb=p.thumbnailUrl||'';const metrics=(p.metrics||[]).filter(m=>m.value!=null).map(m=>`<span>${esc(m.label)} ${fmt(m.value)}</span>`).join('');return `<article class="ig-post-card">${thumb?`<a href="${esc(p.permalink||'#')}" target="_blank" rel="noopener"><img src="${esc(thumb)}" alt="${esc(p.title)}"></a>`:''}<div><h4>${insightPostLink(p,esc(p.title))}</h4><p class="muted small">${esc(p.date)} / ${esc(p.format)} / ${esc(p.account)}</p><p>${esc(p.caption||'')}</p><div class="ig-post-metrics"><span>リーチ ${fmt(p.reach)}</span><span>再生/表示 ${fmt(p.plays)}</span><span>保存 ${fmt(p.saves)}</span><span>シェア ${fmt(p.shares)}</span><span>総反応 ${fmt(interactions)}</span><span>反応率 ${insightRate(p)}</span></div>${metrics?`<div class="ig-tags">${metrics}</div>`:''}</div></article>`}).join('')}</div>`}


