function formatPlanDate(iso){if(!iso)return '';const [y,m,d]=String(iso).split('-').map(Number);if(!y||!m||!d)return '';const dt=new Date(y,m-1,d);const w='日月火水木金土'[dt.getDay()];return `${y}年${m}月${d}日（${w}）`}
function mergePlanDateIntoSchedule(schedule,dateIso){const dateText=formatPlanDate(dateIso);const raw=String(schedule||'').trim();if(!dateText)return raw;const cleaned=raw.replace(/^\d{4}年\d{1,2}月\d{1,2}日（[日月火水木金土]）\s*/, '').replace(/^\d{4}-\d{2}-\d{2}\s*/, '').replace(/^次回撮影日\s*/, '').trim();return cleaned?`${dateText} ${cleaned}`:dateText}
function applyPlanDate(){const dateEl=document.getElementById('plan_date');const scheduleEl=document.getElementById('plan_schedule');if(!dateEl||!scheduleEl)return;scheduleEl.value=mergePlanDateIntoSchedule(scheduleEl.value,dateEl.value)}
function fillPlanForm(){const seed=candidatePlanSeed(currentCandidate());state.planForm={...seed,planned_date:''};['schedule','video_details','plan_content','plan_detail'].forEach(id=>{const el=document.getElementById('plan_'+id);if(el)el.value=seed[id]||''});const dateEl=document.getElementById('plan_date');if(dateEl){dateEl.value='';dateEl.focus()}}
async function createPlanFromForm(){const dateIso=document.getElementById('plan_date')?.value||'';const scheduleInput=document.getElementById('plan_schedule');if(scheduleInput&&dateIso)scheduleInput.value=mergePlanDateIntoSchedule(scheduleInput.value,dateIso);const data={schedule:scheduleInput?.value||'',video_details:document.getElementById('plan_video_details')?.value||'',plan_content:document.getElementById('plan_plan_content')?.value||'',plan_detail:document.getElementById('plan_plan_detail')?.value||'',planned_date:dateIso};state.planForm=data;if(!data.schedule||!data.video_details||!data.plan_content||!data.plan_detail){state.planMessage='未入力項目があります。日程・動画詳細・企画内容・企画詳細を入力してください。';render();return}state.planMessage='企画書を作成中...';render();try{const res=await fetch('/api/plans',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const json=await res.json();if(!res.ok)throw new Error(json.error||'plan_create_failed');state.generatedPlan=json.plan;state.runtime=json.state||state.runtime;state.planMessage='企画書を作成し、動作ログにも記録しました。'}catch(e){state.generatedPlan={document_markdown:['# SNS企画書','','【日程】','',`    ${data.schedule}`,'','【動画詳細】','',`   ${data.video_details}`,'','【企画内容】','',...data.plan_content.split(/\n/).filter(Boolean).map((x,i)=>`   ${i+1}．${x.trim()}`),'','【企画詳細】','',data.plan_detail].join('\n')};state.planMessage='ローカルで企画書を作成しました（API保存は未完了: '+(e.message||e)+'）。'}render()}
function copyPlan(){const text=state.generatedPlan?.document_markdown||'';if(text)navigator.clipboard?.writeText(text);state.planMessage='企画書本文をコピーしました。';render()}
function loadSeenSalesAccounts(){try{state.seenSalesAccounts=JSON.parse(localStorage.getItem('sns_seen_sales_accounts')||'[]')}catch(e){state.seenSalesAccounts=[]}}
function persistSeenSalesAccounts(){localStorage.setItem('sns_seen_sales_accounts',JSON.stringify([...new Set(state.seenSalesAccounts)].slice(0,1000)))}
function mergeSeenSalesAccounts(accounts){(accounts||[]).forEach(x=>{const key=typeof x==='string'?x:(x&&x.key);if(key&&!state.seenSalesAccounts.includes(key))state.seenSalesAccounts.push(key)});persistSeenSalesAccounts()}
async function refreshSalesExportHistory(){try{const res=await fetch('/api/state',{cache:'no-store'});if(!res.ok)throw new Error('HTTP '+res.status);const json=await res.json();state.runtime=json;state.salesScheduler=json.sales_scheduler||state.salesScheduler;state.salesRuns=json.sales_runs||[];state.salesAlerts=json.alerts||[];mergeSeenSalesAccounts(json.sales_exported_accounts||[]);mergeServerSalesProspects(json.sales_new_prospects||[]);if(state.view==='sales')render()}catch(e){console.warn('sales history load failed',e)}}
async function refreshApifyStatus(){
  if(state.apifyStatusLoading)return;
  state.apifyStatusLoading=true;state.apifyStatusError='';
  if(state.view==='instagramSettings'||state.view==='competitor')render();
  try{
    const res=await fetch('/api/apify/status',{cache:'no-store'});
    const json=await res.json();
    if(!res.ok||!json.ok)throw new Error(json.error||json.message||'apify_status_failed');
    state.apifyStatus=json;
  }catch(e){state.apifyStatusError=e.message||String(e)}
  finally{state.apifyStatusLoading=false;if(state.view==='instagramSettings'||state.view==='competitor')render()}
}
function apifyStatusSummary(){const s=state.apifyStatus;if(state.apifyStatusLoading)return {ready:'確認中',detail:'Apify設定を読み込み中',actors:'-',token:'-'};if(state.apifyStatusError)return {ready:'未確認',detail:state.apifyStatusError,actors:'-',token:'-'};if(!s)return {ready:'未確認',detail:'設定画面で再読込してください',actors:'-',token:'-'};const actors=Object.entries(s.actors||{}).filter(([,v])=>v&&v.configured).map(([k])=>k);return {ready:s.ready?'接続可':'未接続',detail:s.note||'秘密値は表示しません',actors:actors.length?actors.join(' / '):'未設定',token:s.token?.exists?`設定済み（末尾 ${s.token.last4||'****'}）`:'未設定'}}
function salesKey(p){return String(p.account||p.url||p.company||'').trim().toLowerCase().replace(/^https?:\/\/(www\.)?instagram\.com\//,'').replace(/[/?#].*$/,'').replace(/^@/,'')}
function isSalesDuplicate(p){return state.seenSalesAccounts.includes(salesKey(p))}
function markSalesExtracted(){rankedProspects().forEach(p=>{if(!isSalesDuplicate(p))state.seenSalesAccounts.push(salesKey(p))});persistSeenSalesAccounts();state.salesExportMessage='表示中の営業候補を抽出済み履歴に記録しました。通常はSheets出力時に自動記録されます。';render()}
function clearSalesExtracted(){state.seenSalesAccounts=[];persistSeenSalesAccounts();state.salesExportMessage='画面内の抽出済み履歴をクリアしました。サーバーに保存済みの出力履歴は次回同期時に再反映されます。';render()}

function defaultSalesCriteria(){return {
  recruitKeywords:'採用,求人,新卒,中途,recruit,career,saiyo,jinji,staff,社員,募集,説明会,インターン,open company,職場紹介,社員紹介',
  targetSignals:'中小,地域,店舗,クリニック,歯科,介護,福祉,美容,建設,物流,製造,工場,保育,clinic,dental,care,kaigo,salon,store,shop,driver,factory,kensetsu,hoiku',
  providerExcludes:'SNSコンサル,SNS運用代行,SNS運用支援,SNSマーケ,Instagram運用代行,インスタ運用代行,TikTok運用代行,ショート動画運用,動画マーケティング支援,採用支援,採用代行,採用コンサル,求人広告,求人媒体,人材紹介,人材派遣,RPO',
  largeExcludes:'mercari,メルカリ,cyberagent,サイバーエージェント,rakuten,楽天,dena,pasona,パソナ,dip,teamlab,チームラボ,mynavi,マイナビ,リクルート,softbank,ソフトバンク,ntt,kddi,toyota,トヨタ,sony,ソニー,panasonic,パナソニック,hitachi,日立,fujitsu,富士通,nec,accenture,アクセンチュア,deloitte,pwc,kpmg,amazon,google,microsoft',
  successAvgReel:10000,
  highScore:75,
  midScore:50,
  minVisibleScore:1,
  weights:{smeFit:28,unknownSize:5,recruitDedicated:20,recruitPost:12,weakRecruit:-20,linkYes:14,linkNo:-10,feed10:8,feed5:5,feedUnknown:4,noReels:18,lowReels:10,reelsUnknown:8,clearAngle:12,lowFrequency:-15,contactHigh:8}
}}
function salesCriteriaKey(){return 'sns_sales_criteria_v2'}
function parseCsvWords(v){return String(v||'').split(/[、,\n]/).map(x=>x.trim().toLowerCase()).filter(Boolean)}
function salesCriteria(){return state.salesCriteria||defaultSalesCriteria()}
function loadSalesCriteria(){try{const saved=JSON.parse(localStorage.getItem(salesCriteriaKey())||'null');state.salesCriteria=saved?{...defaultSalesCriteria(),...saved,weights:{...defaultSalesCriteria().weights,...(saved.weights||{})}}:defaultSalesCriteria()}catch(e){state.salesCriteria=defaultSalesCriteria()}}
function persistSalesCriteria(){localStorage.setItem(salesCriteriaKey(),JSON.stringify(salesCriteria()))}
function resetSalesCriteria(){state.salesCriteria=defaultSalesCriteria();persistSalesCriteria();state.salesCriteriaMessage='判定基準を初期値に戻しました。抽出キーワード・検索条件・スコアリング・除外条件へ即時反映済みです。';render()}
function updateSalesCriteria(field,value){const c={...salesCriteria(),weights:{...salesCriteria().weights}};if(field.startsWith('weights.')){const k=field.split('.')[1];c.weights[k]=Number(value||0)}else if(['successAvgReel','highScore','midScore','minVisibleScore'].includes(field)){c[field]=Number(value||0)}else{c[field]=value||''}state.salesCriteria=c;persistSalesCriteria();state.salesCriteriaMessage='判定基準を保存しました。次の抽出・検索・画面フィルタ・営業価値スコアに自動連動します。';render()}
function includesAnyDynamic(text,words){const hay=String(text||'').toLowerCase();return parseCsvWords(words).some(w=>hay.includes(w))}
function currentSalesCriteriaPayload(){const c=salesCriteria();return {recruitKeywords:c.recruitKeywords,targetSignals:c.targetSignals,providerExcludes:c.providerExcludes,largeExcludes:c.largeExcludes,successAvgReel:c.successAvgReel,highScore:c.highScore,midScore:c.midScore,minVisibleScore:c.minVisibleScore,weights:c.weights}}
function salesCriteriaHtml(){const c=salesCriteria();const w=c.weights||{};return `<section class="card" style="margin-top:16px"><div class="section-title"><div><h3>営業候補判定基準</h3><p class="muted small">ここを編集すると、抽出APIへ渡す検索語、営業対象外フィルタ、画面の営業価値スコア、高営業価値フィルタが自動で切り替わります。</p></div><div class="actions"><button class="mini-btn" onclick="resetSalesCriteria()">初期値に戻す</button></div></div>${state.salesCriteriaMessage?`<div class="notice">${esc(state.salesCriteriaMessage)}</div>`:''}<div class="form-grid"><label class="full">採用アカウント判定キーワード<textarea onchange="updateSalesCriteria('recruitKeywords',this.value)">${esc(c.recruitKeywords)}</textarea></label><label class="full">狙いたい企業・業種シグナル<textarea onchange="updateSalesCriteria('targetSignals',this.value)">${esc(c.targetSignals)}</textarea></label><label class="full">除外：同業者・提供者キーワード<textarea onchange="updateSalesCriteria('providerExcludes',this.value)">${esc(c.providerExcludes)}</textarea></label><label class="full">除外：大手・有名企業キーワード<textarea onchange="updateSalesCriteria('largeExcludes',this.value)">${esc(c.largeExcludes)}</textarea></label><label>成功済み除外ライン（平均リール再生）<input type="number" value="${esc(c.successAvgReel)}" onchange="updateSalesCriteria('successAvgReel',this.value)"></label><label>高営業価値ライン<input type="number" value="${esc(c.highScore)}" onchange="updateSalesCriteria('highScore',this.value)"></label><label>確認後アプローチライン<input type="number" value="${esc(c.midScore)}" onchange="updateSalesCriteria('midScore',this.value)"></label><label>表示する最低スコア<input type="number" value="${esc(c.minVisibleScore)}" onchange="updateSalesCriteria('minVisibleScore',this.value)"></label></div><details class="score-detail"><summary>加点・減点ウェイトを編集</summary><div class="form-grid compact-criteria"><label>中小/地域適合<input type="number" value="${esc(w.smeFit)}" onchange="updateSalesCriteria('weights.smeFit',this.value)"></label><label>採用専用<input type="number" value="${esc(w.recruitDedicated)}" onchange="updateSalesCriteria('weights.recruitDedicated',this.value)"></label><label>採用投稿あり<input type="number" value="${esc(w.recruitPost)}" onchange="updateSalesCriteria('weights.recruitPost',this.value)"></label><label>採用色が弱い<input type="number" value="${esc(w.weakRecruit)}" onchange="updateSalesCriteria('weights.weakRecruit',this.value)"></label><label>採用リンクあり<input type="number" value="${esc(w.linkYes)}" onchange="updateSalesCriteria('weights.linkYes',this.value)"></label><label>リール未活用<input type="number" value="${esc(w.noReels)}" onchange="updateSalesCriteria('weights.noReels',this.value)"></label><label>リール低再生<input type="number" value="${esc(w.lowReels)}" onchange="updateSalesCriteria('weights.lowReels',this.value)"></label><label>提案切り口明確<input type="number" value="${esc(w.clearAngle)}" onchange="updateSalesCriteria('weights.clearAngle',this.value)"></label></div></details><div class="notice"><strong>記載粒度の目安：</strong>文章ではなく、検索結果やプロフィール文に出そうな「判定語」をカンマ/改行で入れてください。<br>・採用判定：採用, 求人, 新卒, 中途, recruit, career のような状態語<br>・狙いたい企業：介護, 歯科, 美容室, 建設, 保育, 物流, 店舗 のような業種/属性語<br>・除外：SNS運用代行, 採用支援, 人材紹介 のような業態語を優先。必要な場合だけ企業名を追加<br>・大手除外：企業名だけでなく、上場, 全国展開, ホールディングス など検索結果に出る語も追加できます</div><div class="notice"><strong>連動中：</strong>「採用キーワード」は抽出検索語へ追加、「除外キーワード」は抽出後フィルタと画面判定へ反映、「成功済み除外ライン」はリール平均再生の除外条件、「高/中ライン」は表示タブの判定に使います。</div></section>`}
function scoreClass(score){return score>=80?'ok':score>=60?'warn':'risk'}
function salesRank(score){const c=salesCriteria();return score>=Number(c.highScore||75)?'高':score>=Number(c.midScore||50)?'中':'低'}
function salesRankClass(score){const c=salesCriteria();return score>=Number(c.highScore||75)?'ok':score>=Number(c.midScore||50)?'warn':'risk'}
function avgReelViews(p){return p.avgReel==null?null:Number(p.avgReel||0)}
function isReelSuccessful(p){const avg=avgReelViews(p);return avg!=null && avg>=Number(salesCriteria().successAvgReel||10000)}
function isLargeEnterpriseCandidate(p){const text=[p.company,p.account,p.sourceNote,p.snippet].join(' ').toLowerCase();return includesAnyDynamic(text,salesCriteria().largeExcludes)}
function isSameIndustryProviderCandidate(p){const text=[p.company,p.account,p.industry,p.kind,p.gap,p.angle,p.snippet].join(' ').toLowerCase();return includesAnyDynamic(text,salesCriteria().providerExcludes)}
function hasSmeFit(p){const text=[p.company,p.account,p.industry,p.type,p.sizeFit,p.sourceNote,p.snippet].join(' ').toLowerCase();return includesAnyDynamic(text,salesCriteria().targetSignals)}
function salesScore(p){
  const avg=avgReelViews(p);
  const c=salesCriteria();const w=c.weights||defaultSalesCriteria().weights;
  const factors=[];
  if(isLargeEnterpriseCandidate(p))return {score:0,status:'営業対象外',reason:'上場大手・有名企業に該当する可能性が高く、初回営業の接触難度が高いため自動除外。',factors:['大手/有名企業を除外']};
  if(isSameIndustryProviderCandidate(p))return {score:0,status:'営業対象外',reason:'SNSコンサル・SNS運用代行・動画マーケ支援などの同業者に該当するため営業候補から除外。',factors:['同業者を除外']};
  if(isReelSuccessful(p))return {score:0,status:'営業対象外',reason:`リール平均再生数が${fmt(avg)}回で基準値${fmt(c.successAvgReel||10000)}回以上。現状うまく運用できているため営業対象外。`,factors:['運用成功済み']};
  let score=0;
  if(hasSmeFit(p)){score+=Number(w.smeFit||0);factors.push('中小・地域/採用難業種寄り');}
  else {score+=Number(w.unknownSize||0);factors.push('企業規模は要確認');}
  if((p.kind||'').includes('採用専用')){score+=Number(w.recruitDedicated||0);factors.push('採用専用アカウント');}
  else if((p.kind||'').includes('採用投稿')){score+=Number(w.recruitPost||0);factors.push('採用投稿あり');}
  else {score+=Number(w.weakRecruit||0);factors.push('採用色が弱い');}
  if(p.link==='採用リンクあり'){score+=Number(w.linkYes||0);factors.push('採用リンクあり');}
  else if(p.link==='採用リンクなし'){score+=Number(w.linkNo||0);factors.push('採用リンクなし');}
  else {factors.push('採用リンクは要確認');}
  if((p.feed||0)>=10){score+=Number(w.feed10||0);factors.push('投稿量あり');}
  else if((p.feed||0)>=5){score+=Number(w.feed5||0);factors.push('一定投稿あり');}
  else if(p.feed==null){score+=Number(w.feedUnknown||0);factors.push('投稿量は公開画面で要確認');}
  if((p.reels||0)===0 && (p.feed||0)>=5){score+=Number(w.noReels||0);factors.push('フィードはあるがリール未活用');}
  else if((p.reels||0)>0 && avg!=null && avg<10000){score+=Number(w.lowReels||0);factors.push('リール平均が1万再生未満');}
  else if(p.reels==null){score+=Number(w.reelsUnknown||0);factors.push('リール活用状況は要確認');}
  if(p.gap && p.angle && p.angle!=='後回し'){score+=Number(w.clearAngle||0);factors.push('改善余地と提案切り口が明確');}
  if((p.type||'').includes('投稿頻度低') || p.status==='対象外候補'){score+=Number(w.lowFrequency||0);factors.push('投稿頻度が低い');}
  if(p.contactability==='高'){score+=Number(w.contactHigh||0);factors.push('営業接点を作りやすい可能性');}
  score=Math.max(0,Math.min(100,score));
  const status=score>=Number(c.highScore||75)?'高確度営業候補':score>=Number(c.midScore||50)?'確認後アプローチ候補':score>0?'低優先候補':'営業対象外';
  const reason=status==='営業対象外'?'企業規模・採用色・投稿量・導線のいずれかが営業対象に合わない。':factors.join('・')+'。';
  return {score,status,reason,factors};
}
function scoredProspects(){return [...prospects,...state.extractedSalesProspects].map(p=>{const s=salesScore(p);return {...p,closeRate:s.score,scoreReason:s.reason,status:s.status,duplicate:isSalesDuplicate(p),salesFactors:s.factors,successfulReel:isReelSuccessful(p),dedupeKey:salesKey(p)}})}
function rankedProspects(){const best=new Map();scoredProspects().forEach(p=>{const k=p.dedupeKey||`${p.company}-${p.account}`;const cur=best.get(k);if(!cur || (p.closeRate||0)>(cur.closeRate||0))best.set(k,p)});return [...best.values()].sort((a,b)=>(b.closeRate||0)-(a.closeRate||0))}
function visibleProspects(){const c=salesCriteria();let rows=rankedProspects().filter(p=>!p.duplicate && !p.successfulReel && (p.closeRate||0)>=Number(c.minVisibleScore||1));if(state.salesFilter==='hot')rows=rows.filter(p=>salesRank(p.closeRate||0)==='高');return rows.map((p,i)=>({...p,rank:i+1}))}
function salesValueHtml(p){const score=p.closeRate||0;return `<div class="score-cell"><span class="pill ${salesRankClass(score)}">営業価値：${score}%</span>${scoreDetailHtml(p)}</div>`}
function scoreDetailHtml(p){const tags=(p.salesFactors||[]).map(f=>`<span class="score-tag">${esc(f)}</span>`).join('');return `<details class="score-detail"><summary>詳細表示</summary><div class="score-panel"><div class="score-main">${esc(p.status||'')}</div>${tags?`<div class="score-tags">${tags}</div>`:''}<div class="score-note">理由：${esc(p.scoreReason||'')}</div><div class="score-note">提案切り口：${esc(p.angle||'')}</div></div></details>`}

function salesExtractionKey(){return 'sns_extracted_sales_prospects'}
function loadExtractedSalesProspects(){try{state.extractedSalesProspects=JSON.parse(localStorage.getItem(salesExtractionKey())||'[]')}catch(e){state.extractedSalesProspects=[]}}
function persistExtractedSalesProspects(){localStorage.setItem(salesExtractionKey(),JSON.stringify(state.extractedSalesProspects.slice(0,80)))}
function salesExtractIndustries(){return ['all','医療・福祉採用','店舗・サービス採用','建設・製造・物流採用','教育・保育採用','BtoB・地域企業採用','IT・エンジニア採用']}
function setSalesExtractKeyword(v){state.salesExtractKeyword=v||''}
function setSalesExtractIndustry(v){state.salesExtractIndustry=v||'all'}
function setSalesExtractLimit(v){state.salesExtractLimit=Math.max(1,Math.min(50,Number(v||SALES_DAILY_LIMIT)))}
function salesDiscoveryMatches(p){const q=String(state.salesExtractKeyword||'').trim().toLowerCase();const industryOk=state.salesExtractIndustry==='all'||(p.industry||'未分類')===state.salesExtractIndustry;const text=[p.company,p.account,p.industry,p.kind,p.gap,p.angle,p.sourceNote].join(' ').toLowerCase();return industryOk&&(!q||text.includes(q))}
function mergeServerSalesProspects(rows){let changed=false;(rows||[]).forEach(p=>{const k=salesKey(p);if(k&&!state.extractedSalesProspects.some(x=>salesKey(x)===k)){state.extractedSalesProspects.push({...p,autoExtracted:true,serverSaved:true,extractedAt:p.firstSeenAt||p.extractedAt||new Date().toISOString()});changed=true}});if(changed)persistExtractedSalesProspects()}
function salesSchedulerSummary(){const sc=state.salesScheduler||{};return {status:sc.lastStatus||'not_run',last:sc.lastRunAt?timeText(sc.lastRunAt):'未実行',next:sc.nextRunAt?timeText(sc.nextRunAt):'毎朝 08:00',newCount:sc.lastNewCount||0,error:sc.lastError||'',label:sc.cronLabel||'毎朝 08:00'}}
async function runSalesMorningJob(){if(state.salesSchedulerLoading)return;state.salesSchedulerLoading=true;state.salesAutoMessage='毎朝自動実行と同じ処理で、複数キーワード巡回→DB/Sheets保存→新規のみ表示→失敗時アラート記録を実行中です...';render();try{const res=await fetch('/api/sales/scheduler',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'run',industry:state.salesExtractIndustry,limit:Math.max(1,Math.min(50,Number(state.salesExtractLimit||SALES_DAILY_LIMIT))),criteria:currentSalesCriteriaPayload()})});const json=await res.json();if(!res.ok||!json.ok)throw new Error(json.detail||json.error||'scheduled_run_failed');state.salesScheduler=json.scheduler||state.salesScheduler;mergeServerSalesProspects(json.newProspects||[]);mergeSeenSalesAccounts(json.exportedKeys||[]);await refreshSalesExportHistory();state.salesAutoMessage=`毎朝自動実行フローを検証しました。新規候補 ${json.newProspects?.length||0}件をDBへ保存し、Sheets出力履歴へ登録しました。画面には新規のみ表示します。`; }catch(e){state.salesAutoMessage='毎朝自動実行フローに失敗しました。失敗アラートへ記録しました: '+(e.message||e);await refreshSalesExportHistory()}finally{state.salesSchedulerLoading=false;render()}}
function salesAlertsHtml(){const alerts=state.salesAlerts||[];if(!alerts.length)return '<p class="muted small">現在、未確認アラートはありません。</p>';return `<div class="alert-list">${alerts.slice(0,5).map(a=>`<article class="notice"><strong>${esc(a.title||a.level)}</strong><br><span class="muted small">${esc(timeText(a.at))} / ${esc(a.status||'open')}</span><p>${esc(a.message||'')}</p></article>`).join('')}</div>`}
async function runSalesAutoExtraction(){
  if(state.salesExtracting)return;
  state.salesExtracting=true;
  state.salesAutoMessage='Apify優先でInstagram採用アカウントを抽出中です（未接続時のみWeb検索へフォールバック、事前登録リストは使いません）...';
  render();
  try{
    const limit=Math.max(1,Math.min(50,Number(state.salesExtractLimit||SALES_DAILY_LIMIT)));
    const res=await fetch('/api/sales/extract-hybrid',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({keyword:state.salesExtractKeyword,industry:state.salesExtractIndustry,limit,criteria:currentSalesCriteriaPayload()})});
    const json=await res.json();
    if(!res.ok||!json.ok)throw new Error(json.detail||json.error||'discover_failed');
    const existing=new Set(scoredProspects().map(p=>p.dedupeKey||salesKey(p)));
    const candidates=(json.prospects||[]).map(p=>{const score=salesScore(p);return {...p,extractedAt:json.searchedAt||new Date().toISOString(),autoExtracted:true,closeRate:score.score,scoreReason:score.reason,status:score.status,duplicate:isSalesDuplicate(p)||existing.has(salesKey(p)),successfulReel:isReelSuccessful(p),salesFactors:score.factors,dedupeKey:salesKey(p)}}).filter(p=>!p.duplicate&&!p.successfulReel&&p.closeRate>=Number(salesCriteria().minVisibleScore||1)).sort((a,b)=>(b.closeRate||0)-(a.closeRate||0)).slice(0,limit);
    let added=0;
    candidates.forEach(p=>{if(!state.extractedSalesProspects.some(x=>salesKey(x)===salesKey(p))){state.extractedSalesProspects.push(p);existing.add(salesKey(p));added++;}});
    persistExtractedSalesProspects();
    const src=json.primary==='apify'&&!json.fallbackUsed?'Apify':(json.fallbackUsed?'Apify未接続のためWeb検索':'Web検索');
    state.salesAutoMessage=added?`${src}から${added}件を営業候補リストへ反映しました。採用色が弱い候補、大手・有名企業、SNSコンサル/採用支援等の提供者、重複、運用成功済み候補は除外済みです。月1000件以内の運用設計に合わせ、営業候補は1日${SALES_DAILY_LIMIT}件までを目安にします。`:'条件に合う新規候補はありませんでした。キーワードを「介護 採用」「美容 採用」「建設 採用」などに変えて再実行してください。';
  }catch(e){state.salesAutoMessage='営業候補抽出に失敗しました: '+(e.message||e)}
  finally{state.salesExtracting=false;render()}
}
function clearSalesAutoExtraction(){state.extractedSalesProspects=[];persistExtractedSalesProspects();state.salesAutoMessage='自動抽出で追加した候補をクリアしました。';render()}
function salesSourceBadge(p){return p.autoExtracted?`<span class="pill purple">自動抽出</span><br><span class="muted small">${esc(p.source||'公開情報')} / ${esc(p.extractedAt?timeText(p.extractedAt):'')}</span>`:'<span class="pill warn">初期候補</span>'}
loadCandidates();
loadExtractedSalesProspects();
loadSeenSalesAccounts();
loadSalesCriteria();
refreshSalesExportHistory();



function researchFormPayload(){return {executor:state.authUser?.name||'管理者',discordMessageId:document.getElementById('research_msg_id')?.value||'画面実行',theme:document.getElementById('research_theme')?.value||'',periodStart:document.getElementById('research_start')?.value||'',periodEnd:document.getElementById('research_end')?.value||'',limit:Number(document.getElementById('research_limit')?.value||10),accounts:document.getElementById('research_accounts')?.value||'',allowExternalSearch:document.getElementById('research_external')?.checked||false,tabs:{candidates:'リサーチ候補一覧',logs:'運用ログ'}}}
async function refreshResearch(){try{const res=await fetch('/api/research/semiauto',{cache:'no-store'});const json=await res.json();if(json.ok){state.researchRows=json.candidates||[];state.researchRuns=json.runs||[];if(state.view==='research')render()}}catch(e){console.warn('research load failed',e)}}
async function runResearchSemiauto(){if(state.researchLoading)return;state.researchLoading=true;state.researchMessage='実行前チェック→Apify取得→候補一覧/運用ログ保存を実行中です...';render();try{const res=await fetch('/api/research/semiauto',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(researchFormPayload())});const json=await res.json();if(!json.ok)throw new Error((json.errors||[]).join(' / ')||json.message||json.error||'research_failed');state.researchRows=json.rows||[];state.researchMessage=`${json.count||0}件をリサーチ候補一覧へ反映しました。採用/不採用は人間判断です。Sheets: 候補${json.sheet_write?.candidates?.appendedRows||0}行 / ログ${json.sheet_write?.logs?.appendedRows||0}行`;await refreshLogs();}catch(e){state.researchMessage='要確認: '+(e.message||e)}finally{state.researchLoading=false;render()}}
function research(app){setTitle('リサーチ半自動化');if(!state.researchRows.length&&!state.researchRuns.length)refreshResearch();const today=new Date().toISOString().slice(0,10);const rows=state.researchRows||[];const governance=[['実行前検証','対象テーマ・期間・件数・Instagram URL/アカウント・出力先タブを検証。未入力は推測実行せず要確認。'],['探索範囲','通常は指定アカウント内のみ。指定外探索はチェックON=人間の明示許可がある時だけ。'],['役割分担','定型処理=Apify/Sheets/ログ、AI=条件整理/要約/理由付け、人間=採用/不採用/指定外許可。'],['状態遷移','AIは未確認/要確認/取得失敗/再探索対象まで。採用/不採用/学習反映済みは人間確定。'],['秘密情報','Apify/Google/DiscordのキーはVercel環境変数のみ。画面・Sheets・ログに平文保存しない。']];app.innerHTML=`${authBadgeHtml()}<div class="grid layout-3" style="margin-top:16px">${metric('候補一覧必須列','23列','AI出力列と人間入力列を分離')}${metric('取得上限','10アカウント×50投稿','候補出力20件/指定外50件まで')}${metric('採用確定','人間のみ','AIは採用可否を確定しない')}</div><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>Discord指示からリサーチ候補を作成</h3><p class="muted small">要件定義の初期運用に合わせ、Discord指示相当の条件を入力し、Apify取得結果を「リサーチ候補一覧」「運用ログ」へ保存します。</p></div><span class="badge">半自動化</span></div>${state.researchMessage?`<div class="notice">${esc(state.researchMessage)}</div>`:''}<div class="form-grid"><label>DiscordメッセージID<input id="research_msg_id" value="画面実行" placeholder="DiscordのメッセージID"></label><label>対象テーマ<input id="research_theme" value="新卒採用向け 就活ノウハウ系"></label><label>対象期間 開始<input id="research_start" type="date" value="${esc(today)}"></label><label>対象期間 終了<input id="research_end" type="date" value="${esc(today)}"></label><label>希望件数<input id="research_limit" type="number" min="1" max="20" value="10"></label><label>指定外探索許可<label class="inline-check"><input id="research_external" type="checkbox"> 人間が許可した場合のみON</label></label><label class="full">対象アカウント（最大10件）<textarea id="research_accounts">${esc(RESEARCH_DEFAULT_ACCOUNTS)}</textarea></label></div><div class="actions"><button class="mini-btn primary" onclick="runResearchSemiauto()" ${state.researchLoading?'disabled':''}>${state.researchLoading?'実行中...':'リサーチ実行'}</button><button class="mini-btn" onclick="refreshResearch()">保存結果を再読込</button><span class="muted small">不足項目がある場合はSheetsへ書かず要確認で返します。</span></div></section><section class="card wide-table-card" style="margin-top:16px"><div class="section-title"><div><h3>リサーチ候補一覧</h3><p class="muted small">採用ステータス、不採用理由分類、不採用理由メモ、次回抽出への反映要否は人間入力欄として保持します。</p></div><span class="badge">${rows.length}件</span></div>${rows.length?rowsToTable(['対象テーマ','探索区分','アカウント','投稿URL','投稿日/種別','数値','AI抽出理由','リスク/状態'],rows.map(r=>`<tr><td>${esc(r.theme)}<br><span class="muted small">${esc(r.period)}</span></td><td>${esc(r.searchScope)}</td><td>${esc(r.account)}</td><td>${r.postUrl&&r.postUrl!=='取得不可'&&r.postUrl!=='要確認'?`<a href="${esc(r.postUrl)}" target="_blank" rel="noopener">投稿を開く</a>`:esc(r.postUrl||'取得不可')}<br><span class="muted small">ID: ${esc(r.postId||'')}</span></td><td>${esc(r.postedAt)} / ${esc(r.postType)}</td><td>再生 ${esc(r.views)}<br>いいね ${esc(r.likes)} / コメント ${esc(r.comments)}</td><td>${esc(r.aiReason)}</td><td>${esc(r.riskNote)}<br>${pill(r.adoptionStatus||'未確認')}</td></tr>`)):'<p class="muted">まだ候補はありません。上のフォームから実行してください。</p>'}</section><section class="card" style="margin-top:16px"><div class="section-title"><h3>要件定義チェック反映</h3><span class="badge">5点化対応</span></div>${rowsToTable(['観点','実装内容'],governance.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td></tr>`))}</section>`}



function monthlyFormPayload(){return {executor:state.authUser?.name||'管理者',targetMonth:document.getElementById('monthly_target_month')?.value||'',account:document.getElementById('monthly_account')?.value||'',dataType:document.getElementById('monthly_data_type')?.value||'both',targetTab:document.getElementById('monthly_target_tab')?.value||'月次レポート_月次全体',previousMonthly:{views:Number(document.getElementById('monthly_prev_views')?.value||0),reach:Number(document.getElementById('monthly_prev_reach')?.value||0),profileAccess:Number(document.getElementById('monthly_prev_profile')?.value||0),linkClicks:Number(document.getElementById('monthly_prev_clicks')?.value||0),followers:Number(document.getElementById('monthly_prev_followers')?.value||0)}}}
async function refreshMonthlyReport(){try{const res=await fetch('/api/monthly-report',{cache:'no-store'});const json=await res.json();if(json.ok){state.monthlyRows=json.rows||[];state.monthlySummaryRows=json.monthlyRows||[];state.monthlyLogs=json.logs||[];if(state.view==='monthlyReport')render()}}catch(e){console.warn('monthly report load failed',e)}}
async function runMonthlyReport(){if(state.monthlyLoading)return;state.monthlyLoading=true;state.monthlyMessage='Meta公式API取得→同一タブ更新許可列チェック→DB/運用ログ保存を実行中です...';render();try{const res=await fetch('/api/monthly-report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(monthlyFormPayload())});const json=await res.json();if(!json.ok)throw new Error((json.errors||[]).join(' / ')||json.message||json.error||'monthly_report_failed');state.monthlyRows=json.contentRows||[];state.monthlySummaryRows=json.monthlyRows||[];state.monthlyLogs=[json.log,...(state.monthlyLogs||[])];state.monthlyMessage=`${(json.contentRows||[]).length}件の投稿別、${(json.monthlyRows||[]).length}件の月次全体を作成しました。ステータス=${json.status}。採用/外部共有は人間判断です。`;await refreshLogs();}catch(e){state.monthlyMessage='要確認: '+(e.message||e)}finally{state.monthlyLoading=false;render()}}
function monthlyStatusPill(status){return pill(status==='取得済み'?'取得済み':status||'要確認')}
function monthlyContentTable(rows){return rows&&rows.length?rowsToTable(['対象月','投稿','再生数','閲覧者数','いいね','保存','プロフアクセス','リンクタップ','取得ステータス','要確認/分析'],rows.map(r=>`<tr><td>${esc(r.targetMonth)}</td><td><strong>${r.postUrl?`<a href="${esc(r.postUrl)}" target="_blank" rel="noopener">${esc(r.postId||'投稿')}</a>`:esc(r.postId||'投稿')}</strong><br><span class="muted small">${esc(r.account)} / ${esc(r.postedAt)} / ${esc(r.postType)}</span></td><td>${fmt(r.views)}</td><td>${fmt(r.reach)}</td><td>${fmt(r.likes)}</td><td>${fmt(r.saves)}</td><td>${fmt(r.profileAccess)}</td><td>${fmt(r.linkClicks)}</td><td>${monthlyStatusPill(r.status)}</td><td>${esc(r.confirmation)}<br><span class="muted small">${esc(r.analysis)}</span></td></tr>`)):'<p class="muted">まだ投稿別データはありません。</p>'}
function monthlySummaryTable(rows){return rows&&rows.length?rowsToTable(['対象月','アカウント','再生数','閲覧者数','プロフ流入','リンクタップ','フォロワー','前月比','取得ステータス','分析コメント'],rows.map(r=>`<tr><td>${esc(r.targetMonth)}</td><td>${esc(r.account)}</td><td>${fmt(r.views)}</td><td>${fmt(r.reach)}</td><td>${fmt(r.profileAccess)}</td><td>${fmt(r.linkClicks)}</td><td>${fmt(r.followers)}</td><td>再生 ${esc(r.viewsMoM)}<br>閲覧者 ${esc(r.reachMoM)}<br>リンク ${esc(r.linkClicksMoM)}</td><td>${monthlyStatusPill(r.status)}</td><td>${esc(r.confirmation)}<br><span class="muted small">${esc(r.analysis)}</span></td></tr>`)):'<p class="muted">まだ月次全体データはありません。</p>'}
function monthlyReport(app){setTitle('月次レポート運用');if(!state.monthlyRows.length&&!state.monthlySummaryRows.length&&!state.monthlyLogs.length)refreshMonthlyReport();const ym=new Date().toISOString().slice(0,7);const accounts=activeAccounts().map(a=>String(a.account||a.username||'').replace(/^@/,'')).filter(Boolean);const accountOptions=(accounts.length?accounts:['ascentbusiness_consulting','ascent.businessconsulting','senpaini_numatta']).map(a=>`<option value="${esc(a)}">@${esc(a)}</option>`).join('');app.innerHTML=`${authBadgeHtml()}<div class="grid layout-3" style="margin-top:16px">${metric('要件定義タブ','月次レポート_運用反映案','Google Sheetsの同一タブ参照/同一タブ反映方針を反映')}${metric('初期運用','Meta公式API接続前提','手入力はAPI非返却・分類・確認値のみ')}${metric('状態管理','未取得/取得済み/要確認/取得不可/反映済み/エラー','AIは採用・外部共有を確定しない')}</div><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>月次レポート作成・反映実行</h3><p class="muted small">対象月・アカウント・データ種別・対象タブを指定し、Meta公式API取得値とSheets入力値を前提に、更新許可列だけへ反映する運用を画面/API化しました。</p></div><span class="badge">初期運用からAPI自動取得</span></div>${state.monthlyMessage?`<div class="notice">${esc(state.monthlyMessage)}</div>`:''}<div class="form-grid"><label>対象月<input id="monthly_target_month" type="month" value="${esc(ym)}"></label><label>対象アカウント<select id="monthly_account">${accountOptions}</select></label><label>対象データ種別<select id="monthly_data_type"><option value="both">コンテンツ別＋月次全体</option><option value="content">コンテンツ別のみ</option><option value="monthly">月次全体のみ</option></select></label><label>更新対象タブ<select id="monthly_target_tab"><option>月次レポート_月次全体</option><option>月次レポート_コンテンツ別</option><option>月次レポート_運用反映案</option></select></label><label>前月 再生数<input id="monthly_prev_views" type="number" value="120000"></label><label>前月 閲覧者数<input id="monthly_prev_reach" type="number" value="76000"></label><label>前月 プロフ流入<input id="monthly_prev_profile" type="number" value="3200"></label><label>前月 リンクタップ<input id="monthly_prev_clicks" type="number" value="520"></label><label>前月 フォロワー<input id="monthly_prev_followers" type="number" value="4480"></label></div><div class="actions"><button class="mini-btn primary" onclick="runMonthlyReport()" ${state.monthlyLoading?'disabled':''}>${state.monthlyLoading?'実行中...':'月次レポート作成'}</button><button class="mini-btn" onclick="refreshMonthlyReport()">保存済みを再読込</button></div></section><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>実装済みデータ契約</h3><p class="muted small">定型処理・生成AI・人間判断を分離し、未入力/列不一致/比較不可は要確認で止めます。</p></div><span class="badge">更新許可列固定</span></div>${rowsToTable(['区分','実装内容','更新/判断範囲'],[`<tr><td>定型処理</td><td>対象月判定、対象行抽出、Meta公式API取得、比率/前月比、DB保存、運用ログ</td><td>AI更新許可列のみ</td></tr>`,`<tr><td>生成AI</td><td>数値要約、異常値コメント、改善示唆案</td><td>分析コメント案まで</td></tr>`,`<tr><td>人間判断</td><td>対象アカウント指定、API非返却項目入力、異常値採否、公開判断</td><td>採用/不採用/外部共有の確定</td></tr>`])}</section><section class="card" style="margin-top:16px"><div class="section-title"><h3>月次全体 出力プレビュー</h3><span class="badge">月次粒度</span></div>${monthlySummaryTable(state.monthlySummaryRows)}</section><section class="card" style="margin-top:16px"><div class="section-title"><h3>コンテンツ別 出力プレビュー</h3><span class="badge">投稿粒度</span></div>${monthlyContentTable(state.monthlyRows)}</section><section class="card" style="margin-top:16px"><div class="section-title"><h3>ガバナンス・合格基準</h3><span class="badge">10章/11章反映</span></div><ul class="risk-list"><li>秘密情報/APIトークンは画面・Sheets・ログへ出力しません。</li><li>対象月・対象アカウント・対象タブ・データ種別が不足した場合は requires_confirmation で停止します。</li><li>AIは人間入力列、識別キー列、権限管理、数式列を更新しません。</li><li>重複更新防止のため、対象月×アカウント×投稿ID/投稿URLをキーにします。</li><li>APIエラー・列不一致・比較対象不明は要確認/エラーとして運用ログに残します。</li></ul></section>`}

