async function exportSalesToSheets(){const rows=visibleProspects();state.salesExporting=true;state.salesExportMessage='スプレッドシートへ出力中...';render();try{const res=await fetch('/api/sales/export-sheets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:'sales_screen',prospects:rows})});const json=await res.json();if(!res.ok)throw new Error(json.error||json.detail||'export_failed');state.runtime=json.state||state.runtime;mergeSeenSalesAccounts(json.sales_exported_accounts||json.state?.sales_exported_accounts||rows.map(p=>salesKey(p)));const w=json.sheet_write||{};state.salesExportMessage=`営業候補リストをスプレッドシートへ出力し、出力済み履歴にも自動記録しました（${w.tab||'05_営業候補アカウント'} / ${w.updatedRows||0}行 / 検証 ${w.verified?'OK':'要確認'}）。次回の候補生成では同じInstagramアカウントを自動除外します。`;}catch(e){state.salesExportMessage='スプレッドシート出力に失敗しました: '+(e.message||e);}finally{state.salesExporting=false;render()}}
function sales(app){setTitle('営業候補アカウント');const rows=visibleProspects();const all=rankedProspects();const sourceDupCount=scoredProspects().length-all.length;const hiddenSeen=all.filter(p=>p.duplicate).length;const hiddenSuccess=all.filter(p=>p.successfulReel).length;const autoCount=state.extractedSalesProspects.length;const hot=rows.filter(p=>salesRank(p.closeRate||0)==='高').length;const industryOptions=salesExtractIndustries().map(x=>x==='all'?`<option value="all" ${state.salesExtractIndustry==='all'?'selected':''}>全業界</option>`:`<option value="${esc(x)}" ${state.salesExtractIndustry===x?'selected':''}>${esc(x)}</option>`).join('');const ss=salesSchedulerSummary();app.innerHTML=`<div class="grid layout-3">${metric('高確度候補',hot+'件','重複と1万再生以上を最初から除外')}${metric('自動抽出追加',autoCount+'件','Apify優先で抽出した中小・地域候補を営業価値順に追加')}${metric('自動除外',hiddenSeen+hiddenSuccess+sourceDupCount+'件',`履歴重複 ${hiddenSeen} / 同一候補 ${sourceDupCount} / 成功済み ${hiddenSuccess}`)}</div><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>本番運用：毎朝自動抽出フロー</h3><p class="muted small">毎朝8時に採用難業種キーワードを巡回し、DBへ保存、Sheets出力履歴へ記録、画面には未出力/未確認の新規候補だけを表示します。失敗時はこの画面のアラートに残します。</p></div><span class="badge">${esc(ss.label)}</span></div><div class="grid layout-3">${metric('最終実行',ss.last,ss.status==='success'?'正常完了':ss.status==='failed'?'失敗':'未実行')}${metric('次回予定',ss.next,'Asia/Tokyo基準')}${metric('前回新規',ss.newCount+'件',ss.error?ss.error:'DB/Sheets保存対象')}</div><div class="actions"><button class="mini-btn primary" onclick="runSalesMorningJob()" ${state.salesSchedulerLoading?'disabled':''}>${state.salesSchedulerLoading?'実行中...':'今すぐ定期抽出を実行'}</button><button class="mini-btn" onclick="refreshSalesExportHistory()">状態を再読込</button><span class="muted small">DB保存 / Sheets保存履歴 / 新規のみ表示 / 失敗時アラートまで一括確認</span></div>${salesAlertsHtml()}</section><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>営業候補アカウント自動抽出</h3><p class="muted small">Apifyを優先してInstagram採用/企業アカウントを探し、未接続時のみWeb検索へフォールバックします。大手・有名企業を除外したうえで、採用難業種・中小/地域企業・SNS改善余地を営業価値として判定します。事前登録リストは使わず、DM自動送信も行いません。</p></div><span class="badge">自動抽出</span></div><div class="form-grid"><label>検索キーワード<input value="${esc(state.salesExtractKeyword)}" oninput="setSalesExtractKeyword(this.value)" placeholder="例：採用、recruit、career、エンジニア"></label><label>業界<select onchange="setSalesExtractIndustry(this.value)">${industryOptions}</select></label><label>抽出上限<input type="number" min="1" max="50" value="${esc(state.salesExtractLimit)}" onchange="setSalesExtractLimit(this.value)"></label></div><div class="actions"><button class="mini-btn primary" onclick="runSalesAutoExtraction()" ${state.salesExtracting?'disabled':''}>${state.salesExtracting?'抽出中...':'Apify優先で営業候補を抽出'}</button><button class="mini-btn ghost" onclick="clearSalesAutoExtraction()">自動抽出分をクリア</button><span class="muted small">除外条件：出力済み重複 / 同一Instagram / 大手・有名企業 / SNSコンサル・採用支援等の提供者 / リール平均1万再生以上 / 採用色が弱い候補</span></div>${state.salesAutoMessage?`<div class="notice">${esc(state.salesAutoMessage)}</div>`:''}</section><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>Instagram企業採用アカウント 営業候補リスト</h3><p class="muted small">過去にSheetsへ出力したInstagramアカウントはサーバー側の出力履歴から自動判別し、最初から候補に出しません。同一Instagramアカウント・リール平均1万再生以上の運用成功企業も除外し、重複しない営業候補だけを営業価値順に並べます。DM自動送信は行いません。</p></div><div class="actions"><button class="mini-btn primary" onclick="exportSalesToSheets()" ${state.salesExporting?'disabled':''}>表示中リストをSheets出力</button></div></div>${state.salesExportMessage?`<div class="notice">${esc(state.salesExportMessage)}</div>`:''}<div class="actions"><button class="mini-btn ${state.salesFilter==='all'?'primary':''}" onclick="state.salesFilter='all';render()">営業候補</button><button class="mini-btn ${state.salesFilter==='hot'?'primary':''}" onclick="state.salesFilter='hot';render()">高営業価値のみ</button><span class="muted small">過去のSheets出力履歴を自動参照して重複除外済み / 出力すると次回以降の除外履歴に自動登録</span></div>${rowsToTable(['順位','企業名','Instagram','抽出元','営業価値','投稿状況','改善余地','提案切り口'],rows.map(p=>`<tr><td><strong>${p.rank}</strong></td><td><strong>${esc(p.company)}</strong><br><span class="muted small">${esc(p.kind)}${p.industry?' / '+esc(p.industry):''}</span></td><td>${p.accountUrl?`<a href="${esc(p.accountUrl)}" target="_blank" rel="noopener"><strong>${esc(p.account)}</strong></a>`:esc(p.account)}</td><td>${salesSourceBadge(p)}</td><td>${salesValueHtml(p)}</td><td>フィード ${p.feed==null?'要確認':p.feed+'件'} / リール ${p.reels==null?'要確認':p.reels+'件'}<br><span class="muted small">平均再生 ${p.avgReel?fmt(p.avgReel):'要確認'} / 1万再生以上: ${p.avgReel==null?'要確認':(p.successfulReel?'はい':'いいえ')}</span></td><td>${esc(p.gap)}</td><td>${esc(p.angle)}</td></tr>`))}</section>${salesCriteriaHtml()}`}


function instagramSettings(app){setTitle('Instagram連携設定');if(!state.apifyStatus&&!state.apifyStatusLoading&&!state.apifyStatusError)refreshApifyStatus();const apify=apifyStatusSummary();const redirect=window.location.origin+'/api/meta/callback';const envRows=[['META_GRAPH_API_VERSION','v21.0','Graph APIのバージョン'],['META_APP_ID','Meta for Developersで作成するアプリID','公開値だが管理者画面だけに表示'],['META_APP_SECRET','Metaアプリのシークレット','Vercel環境変数にのみ保存'],['META_REDIRECT_URI',redirect,'Metaログイン後の戻り先URL'],['FACEBOOK_PAGE_ID','連携済みFacebookページID','Instagramビジネスアカウント取得に使用'],['INSTAGRAM_BUSINESS_ACCOUNT_ID','InstagramビジネスアカウントID','インサイト取得対象'],['META_ACCESS_TOKEN','長期アクセストークン','Discordや画面には表示しない'],['APIFY_TOKEN',apify.token,'競合バズ抽出・営業候補抽出で使用'],['APIFY_INSTAGRAM_PROFILE_ACTOR / HASHTAG / SEARCH',apify.actors,'設定済みActor IDだけを表示']];const scopeRows=[['instagram_basic','Instagramアカウント/投稿の基本情報を読む','必要'],['instagram_manage_insights','自社Instagramのインサイトを読む','必要'],['pages_show_list','管理しているFacebookページ一覧を取得','必要'],['pages_read_engagement','Facebookページに紐づくInstagram情報を読む','必要'],['投稿作成/コメント/DM権限','使用しない','初期は読み取り専用']];const flowRows=[['1','Instagramをプロアカウント化','ビジネスまたはクリエイターに切替'],['2','Facebookページ連携','対象InstagramをFacebookページへリンク'],['3','Metaアプリ作成','Meta for DevelopersでBusiness用途のアプリを作成'],['4','権限設定','上記の読み取り権限のみを追加'],['5','Vercel環境変数設定','シークレット値はVercelに保存し、チャットには貼らない'],['6','取得テスト','/api/instagram-insights で自社アカウントの読み取り確認']];app.innerHTML=`${authBadgeHtml()}<div class="grid layout-3" style="margin-top:16px">${metric('Meta連携状態','未接続','本番環境変数設定後に接続確認')}${metric('Apify連携状態',apify.ready,apify.detail)}${metric('権限方針','読み取り専用','投稿・DM自動送信は行わない')}</div><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>Instagram API連携設定</h3><p class="muted small">Meta Graph APIで自社Instagramビジネスアカウントのインサイトを読み取り、Instagram分析画面へ反映するための設定画面です。実アカウント連携は管理者確認後に進めます。</p></div><span class="badge">管理者設定</span></div><div class="connection-panel"><div><strong>接続開始</strong><p class="muted small">Metaログインを開始し、Facebookページに紐づくInstagramビジネスアカウントを選択します。</p></div><button class="mini-btn primary" onclick="window.location.href='/api/meta/login'">Instagram連携を開始</button><button class="mini-btn" onclick="go('instagram')">分析画面を確認</button></div><div class="notice"><strong>重要：</strong>アクセストークン・App Secretは画面やチャットに貼らず、VercelのEnvironment Variablesへ保存します。このデモでは外部送信・DM送信は行いません。</div></section><div class="grid layout-2" style="margin-top:16px"><section class="card"><div class="section-title"><h3>必要なMeta権限</h3><span class="badge">読み取り</span></div>${rowsToTable(['権限','用途','扱い'],scopeRows.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td><td>${pill(r[2])}</td></tr>`))}</section><section class="card"><div class="section-title"><h3>連携手順</h3><span class="badge">本番化準備</span></div>${rowsToTable(['Step','作業','内容'],flowRows.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`))}</section></div><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>Apify設定状態</h3><p class="muted small">旧URL側で確認していた /api/apify/status の内容を、この管理画面へ統合しました。秘密値は出さず、設定済み/未設定だけ確認できます。</p></div><button class="mini-btn" onclick="refreshApifyStatus()">Apify状態を再読込</button></div><div class="grid layout-3">${metric('APIFY_TOKEN',apify.token,'値そのものは表示しません')}${metric('設定済みActor',apify.actors,'Instagram Profile / Hashtag / Search など')}${metric('利用可否',apify.ready,apify.detail)}</div></section><section class="card" style="margin-top:16px"><div class="section-title"><div><h3>Vercel環境変数</h3><p class="muted small">API接続に必要な値をサーバー側で保持します。秘密情報はフロントへ出さず、ログにも残しません。</p></div><span class="badge">Secrets</span></div>${rowsToTable(['環境変数','設定値/例','用途'],envRows.map(r=>`<tr><td><strong>${esc(r[0])}</strong></td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`))}</section><section class="card" style="margin-top:16px"><div class="section-title"><h3>取得後にInstagram分析へ反映する項目</h3><span class="badge">反映先</span></div><div class="grid layout-3"><article class="item"><strong>アカウントインサイト</strong><p>フォロワー、リーチ、インプレッション、プロフィールアクセス、Web/採用リンククリック。</p></article><article class="item"><strong>投稿別インサイト</strong><p>投稿ごとのリーチ、保存、プロフィール遷移、エンゲージメント率を比較。</p></article><article class="item"><strong>改善提案</strong><p>取得値をもとに、投稿後分析・次回企画・動画別比較へ反映。</p></article></div></section>`}

function logs(app){setTitle('動作ログ');if(!state.runtime&&!state.loadingRuntime&&!state.runtimeError)refreshLogs();const audit=[...((state.runtime&&state.runtime.audit_logs)||[])].reverse();const recent=audit.slice(0,80);const externalSent=audit.filter(l=>l.external_sent===true).length;const externalAi=audit.filter(l=>l.external_ai_used===true).length;const sheetWrites=audit.filter(l=>l.sheet_write).length;app.innerHTML=`
<div class="grid layout-3">
${metric('ログ件数',String(audit.length),'API / 画面操作 / Sheets反映履歴')}
${metric('外部送信あり',String(externalSent)+'件','SNS投稿・DM送信は行わない設計')}
${metric('Sheets書込履歴',String(sheetWrites)+'件','分析・企画案の反映履歴')}
</div>
<section class="card" style="margin-top:16px"><div class="section-title"><div><h3>動作ログ一覧</h3><p class="muted small">AI分析、Google Sheets反映、承認状態変更、レポート作成などの実行履歴を確認できます。最新80件を表示します。</p></div><button class="secondary" onclick="refreshLogs()">最新ログを再読込</button></div>
${state.loadingRuntime?'<p class="muted">ログ取得中...</p>':''}${state.runtimeError?`<p class="error">ログ取得エラー: ${esc(state.runtimeError)}</p>`:''}
${rowsToTable(['日時','処理','対象/詳細','AI利用','外部送信','Sheets'],recent.map(l=>`<tr><td>${esc(timeText(l.at))}</td><td><strong>${esc(actionLabel(l.action))}</strong><br><span class="muted small">${esc(l.action||'')}</span></td><td>${esc(compactDetail(l))}</td><td>${boolPill(l.external_ai_used)}</td><td>${boolPill(l.external_sent)}</td><td>${l.sheet_write?pill(l.sheet_write.error?'要確認':'反映あり'):pill('なし')}</td></tr>`))}</section>
<section class="card" style="margin-top:16px"><h3>ログで確認できること</h3><ul class="risk-list"><li>分析結果をGoogle Sheetsへ反映した履歴を確認できます。</li><li>外部送信が発生したかを確認できます。SNS投稿・DM自動送信は原則「なし」です。</li><li>AIを使った下書き生成や分析実行は、AI利用欄で確認できます。</li></ul></section>`}
function rules(app){setTitle(isAdmin()?'運用ルール':'共有範囲');app.innerHTML=`${authBadgeHtml()}<div class="grid layout-2" style="margin-top:16px"><section class="card"><h3>クライアント共有範囲</h3><ul class="risk-list"><li>会社単位でログインし、その会社に紐づくInstagram/TikTok分析結果だけを表示します。</li><li>1社に複数SNSアカウントがある場合も、会社ID配下のアカウントとしてまとめて表示します。</li><li>クライアントには営業候補、業界別トレンド投稿分析、動作ログ、内部設定、他社データは表示しません。</li></ul></section><section class="card"><h3>管理者の範囲</h3><ul class="risk-list"><li>管理者は会社選択で自社・A社・B社の分析表示を切り替えられます。</li><li>管理者のみ、営業候補・業界別トレンド投稿分析・改善仮説・動作ログなど内部運用画面を確認できます。</li><li>本番化時はフロント非表示だけでなく、API側でもrole/company_idチェックを行います。</li></ul></section></div><section class="card" style="margin-top:16px"><h3>デモID</h3>${rowsToTable(['区分','ログインID','パスワード','表示範囲'],demoUsers.map(u=>`<tr><td>${u.role==='admin'?'管理者':'クライアント'}</td><td>${esc(u.loginId)}</td><td>${esc(u.password)}</td><td>${u.role==='admin'?'全社・全機能':'自社SNS分析のみ'}</td></tr>`))}</section>`}


refreshInstagramInsights();
render();
